final_sql:
SELECT AVG(TotalPrice) AS AverageTotalPrice
FROM (
    SELECT t.TransactionID, t.CustomerID, t.Amount, t.Price, (t.Amount * t.Price) AS TotalPrice
    FROM transactions_1k t
    JOIN (
        SELECT CustomerID
        FROM customers
        WHERE Currency = 'EUR'
    ) c ON t.CustomerID = c.CustomerID
) AS euro_transactions;

